CREATE TABLE tenants(id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE owners(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL);
CREATE TABLE warehouses(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, timezone TEXT NOT NULL DEFAULT 'America/Sao_Paulo');
CREATE TABLE users(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','staff','owner','owner_readonly','receiver','picker','packer','finance')), owner_id TEXT REFERENCES owners(id), token_hash TEXT UNIQUE NOT NULL, active INTEGER NOT NULL DEFAULT 1, expires_at TEXT);
CREATE TABLE user_warehouses(user_id TEXT NOT NULL REFERENCES users(id), warehouse_id TEXT NOT NULL REFERENCES warehouses(id), PRIMARY KEY(user_id,warehouse_id));
CREATE TABLE locations(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), warehouse_id TEXT NOT NULL REFERENCES warehouses(id), code TEXT NOT NULL, UNIQUE(warehouse_id,code));
CREATE TABLE skus(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), owner_id TEXT NOT NULL REFERENCES owners(id), code TEXT NOT NULL, barcode TEXT NOT NULL, name TEXT NOT NULL, UNIQUE(owner_id,code), UNIQUE(owner_id,barcode));
CREATE TABLE stores(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), owner_id TEXT NOT NULL REFERENCES owners(id), name TEXT NOT NULL, UNIQUE(owner_id,name));
CREATE TABLE receipts(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), owner_id TEXT NOT NULL REFERENCES owners(id), warehouse_id TEXT NOT NULL REFERENCES warehouses(id), sku_id TEXT NOT NULL REFERENCES skus(id), reference TEXT NOT NULL, qty INTEGER NOT NULL CHECK(qty>0), accepted_qty INTEGER, rejected_qty INTEGER, location_id TEXT REFERENCES locations(id), status TEXT NOT NULL CHECK(status IN ('RECEIVED','QC_DONE','PUTAWAY')), created_at TEXT NOT NULL, UNIQUE(owner_id,warehouse_id,reference));
CREATE TABLE orders(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), owner_id TEXT NOT NULL REFERENCES owners(id), warehouse_id TEXT NOT NULL REFERENCES warehouses(id), store_id TEXT NOT NULL REFERENCES stores(id), reference TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('CREATED','RESERVED','PICKING','PICKED','VERIFIED','PACKED','SHIPPED','CANCELLED')), package_reference TEXT, tracking_number TEXT, carrier TEXT, created_at TEXT NOT NULL, UNIQUE(store_id,reference));
CREATE TABLE order_lines(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), order_id TEXT NOT NULL REFERENCES orders(id), sku_id TEXT NOT NULL REFERENCES skus(id), qty INTEGER NOT NULL CHECK(qty>0), verified_qty INTEGER NOT NULL DEFAULT 0 CHECK(verified_qty>=0 AND verified_qty<=qty), UNIQUE(order_id,sku_id));
CREATE TABLE inventory(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), owner_id TEXT NOT NULL REFERENCES owners(id), warehouse_id TEXT NOT NULL REFERENCES warehouses(id), sku_id TEXT NOT NULL REFERENCES skus(id), location_id TEXT NOT NULL REFERENCES locations(id), on_hand INTEGER NOT NULL DEFAULT 0 CHECK(on_hand>=0), reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=on_hand), picked INTEGER NOT NULL DEFAULT 0 CHECK(picked>=0 AND picked<=reserved), UNIQUE(owner_id,warehouse_id,sku_id,location_id));
CREATE TABLE allocations(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), order_id TEXT NOT NULL REFERENCES orders(id), line_id TEXT NOT NULL REFERENCES order_lines(id), inventory_id TEXT NOT NULL REFERENCES inventory(id), qty INTEGER NOT NULL CHECK(qty>0), picked_qty INTEGER NOT NULL DEFAULT 0 CHECK(picked_qty>=0 AND picked_qty<=qty), status TEXT NOT NULL CHECK(status IN ('ACTIVE','SHIPPED','RELEASED')), UNIQUE(line_id,inventory_id));
CREATE TABLE ledger(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), owner_id TEXT NOT NULL REFERENCES owners(id), warehouse_id TEXT NOT NULL REFERENCES warehouses(id), sku_id TEXT NOT NULL REFERENCES skus(id), location_id TEXT NOT NULL REFERENCES locations(id), inventory_id TEXT NOT NULL REFERENCES inventory(id), event_type TEXT NOT NULL, source_id TEXT NOT NULL, on_hand_delta INTEGER NOT NULL, reserved_delta INTEGER NOT NULL, picked_delta INTEGER NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), idempotency_key TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE returns(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), owner_id TEXT NOT NULL REFERENCES owners(id), warehouse_id TEXT NOT NULL REFERENCES warehouses(id), order_id TEXT NOT NULL REFERENCES orders(id), sku_id TEXT NOT NULL REFERENCES skus(id), reference TEXT NOT NULL, qty INTEGER NOT NULL CHECK(qty>0), accepted_qty INTEGER, rejected_qty INTEGER, location_id TEXT REFERENCES locations(id), status TEXT NOT NULL CHECK(status IN ('EXPECTED','RECEIVED','QC_DONE','PUTAWAY')), created_at TEXT NOT NULL, UNIQUE(owner_id,reference));
CREATE TABLE fees(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), owner_id TEXT NOT NULL REFERENCES owners(id), warehouse_id TEXT NOT NULL REFERENCES warehouses(id), order_id TEXT NOT NULL REFERENCES orders(id), code TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents>0), currency TEXT NOT NULL DEFAULT 'BRL' CHECK(currency='BRL'), created_at TEXT NOT NULL, UNIQUE(order_id,code));
CREATE TABLE idempotency(tenant_id TEXT NOT NULL REFERENCES tenants(id), actor_id TEXT NOT NULL REFERENCES users(id), key TEXT NOT NULL, request_hash TEXT NOT NULL, response TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(tenant_id,actor_id,key));
CREATE TABLE audit(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), actor_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL, resource_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX inventory_scope ON inventory(tenant_id,owner_id,warehouse_id,sku_id);
CREATE INDEX ledger_scope ON ledger(tenant_id,owner_id,warehouse_id,created_at);
CREATE INDEX orders_scope ON orders(tenant_id,owner_id,warehouse_id,status);
CREATE INDEX receipts_scope ON receipts(tenant_id,owner_id,warehouse_id,status);
CREATE INDEX allocations_order ON allocations(tenant_id,order_id,status);
CREATE TRIGGER ledger_no_update BEFORE UPDATE ON ledger BEGIN SELECT RAISE(ABORT,'append-only ledger'); END;
CREATE TRIGGER ledger_no_delete BEFORE DELETE ON ledger BEGIN SELECT RAISE(ABORT,'append-only ledger'); END;
CREATE TRIGGER audit_no_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'append-only audit'); END;
CREATE TRIGGER audit_no_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'append-only audit'); END;
